import {AsyncLocalStorage} from 'node:async_hooks'; export const context=new AsyncLocalStorage<any>(); export class AuthError extends Error {constructor(message:string,public status:number){super(message)}} export const getSession=async()=>context.getStore()?.session||null; export const getSessionUser=async()=>(await getSession())?.user||null; export const requireUser=async()=>{const u=await getSessionUser();if(!u)throw new AuthError('Sign in',401);return u}; export const requireRole=async()=>{const u=await requireUser();if(u.role!=='admin')throw new AuthError('Forbidden',403);return u}; export const atLeast=(role:string,min:string)=>['visitor','member','moderator','editor','admin'].indexOf(role)>=['visitor','member','moderator','editor','admin'].indexOf(min); export const canModerate=(u:any)=>u&&atLeast(u.role,'moderator'); export const canPublishOfficial=(u:any)=>u&&atLeast(u.role,'editor');